import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.D9QjdNhv.js";const u=JSON.parse('{"title":"Estrutura da Planilha Excel","description":"","frontmatter":{},"headers":[],"relativePath":"guia/planilha-excel.md","filePath":"guia/planilha-excel.md","lastUpdated":null}'),l={name:"guia/planilha-excel.md"};function r(c,t,n,s,i,g){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="estrutura-da-planilha-excel" tabindex="-1">Estrutura da Planilha Excel <a class="header-anchor" href="#estrutura-da-planilha-excel" aria-label="Permalink to &quot;Estrutura da Planilha Excel&quot;">​</a></h1><p>A planilha <code>CONTROLE PAGAMENTOS.xlsx</code> é a principal ferramenta legada do usuário para acompanhamento do acordo. O <strong>App-Recibos</strong> opera com garantia de <strong>zero quebra de estrutura</strong> e <strong>preservação total de gráficos e fórmulas</strong>.</p><h2 id="abas-e-tabelas-estruturadas" tabindex="-1">Abas e Tabelas Estruturadas <a class="header-anchor" href="#abas-e-tabelas-estruturadas" aria-label="Permalink to &quot;Abas e Tabelas Estruturadas&quot;">​</a></h2><h3 id="aba-1-controle-geral" tabindex="-1">Aba 1: <code>Controle Geral</code> <a class="header-anchor" href="#aba-1-controle-geral" aria-label="Permalink to &quot;Aba 1: `Controle Geral`&quot;">​</a></h3><p>Contém a tabela estruturada <code>GERAL</code> com o resumo consolidado de cada beneficiário:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Coluna</th><th style="text-align:left;">Descrição</th><th style="text-align:left;">Exemplo de Conteúdo</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NOME</code></td><td style="text-align:left;">Nome completo do herdeiro</td><td style="text-align:left;">ELISANGELA MARIA VASCONCELOS DE ARAÚJO</td></tr><tr><td style="text-align:left;"><code>CPF</code></td><td style="text-align:left;">Documento do herdeiro</td><td style="text-align:left;"><code>341.267.018-93</code></td></tr><tr><td style="text-align:left;"><code>CONTRATO</code></td><td style="text-align:left;">Valor total acordado</td><td style="text-align:left;"><code>30000.00</code></td></tr><tr><td style="text-align:left;"><code>PAGO</code></td><td style="text-align:left;">Soma calculada das parcelas pagas</td><td style="text-align:left;"><code>=SUMIF(PARCELAS[NOME], GERAL[@NOME], PARCELAS[VALOR])</code></td></tr><tr><td style="text-align:left;"><code>SALDO</code></td><td style="text-align:left;">Saldo devedor dinâmico restante</td><td style="text-align:left;"><code>=GERAL[@CONTRATO] - GERAL[@PAGO]</code></td></tr><tr><td style="text-align:left;"><code>STATUS</code></td><td style="text-align:left;">Status da quitação total</td><td style="text-align:left;"><code>=IF(GERAL[@SALDO]&lt;=0, &quot;QUITADO&quot;, &quot;EM ABERTO&quot;)</code></td></tr><tr><td style="text-align:left;"><code>BANCO</code></td><td style="text-align:left;">Instituição financeira</td><td style="text-align:left;"><code>104 - Caixa Econômica Federal</code></td></tr><tr><td style="text-align:left;"><code>AG</code></td><td style="text-align:left;">Agência bancária</td><td style="text-align:left;"><code>0001</code></td></tr><tr><td style="text-align:left;"><code>CONTA</code></td><td style="text-align:left;">Número da conta bancária</td><td style="text-align:left;"><code>123456-7</code></td></tr><tr><td style="text-align:left;"><code>OP</code></td><td style="text-align:left;">Operação (se aplicável)</td><td style="text-align:left;"><code>013</code></td></tr><tr><td style="text-align:left;"><code>TIPO</code></td><td style="text-align:left;">Tipo de conta</td><td style="text-align:left;"><code>CORRENTE</code> ou <code>POUPANÇA</code></td></tr><tr><td style="text-align:left;"><code>PIX</code></td><td style="text-align:left;">Chave Pix cadastrada</td><td style="text-align:left;"><code>(82)99929-1488</code></td></tr></tbody></table><h3 id="aba-2-registro-de-pagamentos" tabindex="-1">Aba 2: <code>Registro de Pagamentos</code> <a class="header-anchor" href="#aba-2-registro-de-pagamentos" aria-label="Permalink to &quot;Aba 2: `Registro de Pagamentos`&quot;">​</a></h3><p>Contém a tabela estruturada <code>PARCELAS</code> (colunas A a O) e a tabela auxiliar de meses <code>MESES</code> (colunas Q e R):</p><table tabindex="0"><thead><tr><th style="text-align:center;">Coluna</th><th style="text-align:left;">Cabeçalho</th><th style="text-align:left;">Tipo / Fórmula</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>A</strong></td><td style="text-align:left;"><code>NOME</code></td><td style="text-align:left;">Texto do beneficiário</td></tr><tr><td style="text-align:center;"><strong>B</strong></td><td style="text-align:left;"><code>CPF</code></td><td style="text-align:left;"><code>=IFERROR(INDEX(GERAL[CPF],MATCH(PARCELAS[[#This Row],[NOME]],GERAL[NOME],0)),&quot;-&quot;)</code></td></tr><tr><td style="text-align:center;"><strong>C</strong></td><td style="text-align:left;"><code>PARCELA</code></td><td style="text-align:left;"><code>=COUNTIF(PARCELAS[[#Headers],[NOME]]:PARCELAS[[#This Row],[NOME]],PARCELAS[[#This Row],[NOME]])</code></td></tr><tr><td style="text-align:center;"><strong>D</strong></td><td style="text-align:left;"><code>STATUS</code></td><td style="text-align:left;"><code>PAGO</code> ou <code>PREVISTO</code></td></tr><tr><td style="text-align:center;"><strong>E</strong></td><td style="text-align:left;"><code>VALOR</code></td><td style="text-align:left;">Valor da parcela (ex: <code>1000.00</code> ou <code>500.00</code>)</td></tr><tr><td style="text-align:center;"><strong>F</strong></td><td style="text-align:left;"><code>DATA PREVISTA</code></td><td style="text-align:left;">Data agendada da parcela no formato de data do Excel</td></tr><tr><td style="text-align:center;"><strong>G</strong></td><td style="text-align:left;"><code>DATA PAGAMENTO</code></td><td style="text-align:left;">Data de quitação efetiva (preenchida apenas quando <code>STATUS</code> for <code>PAGO</code>)</td></tr><tr><td style="text-align:center;"><strong>H</strong></td><td style="text-align:left;"><code>FORMA PGTO</code></td><td style="text-align:left;"><code>PIX</code>, <code>TED</code>, <code>TEV</code> ou <code>ESPÉCIE</code></td></tr><tr><td style="text-align:center;"><strong>I</strong></td><td style="text-align:left;"><code>CHAVE PIX</code></td><td style="text-align:left;"><code>=IFERROR(INDEX(GERAL[PIX],MATCH(PARCELAS[[#This Row],[NOME]],GERAL[NOME],0)),&quot;-&quot;)</code></td></tr><tr><td style="text-align:center;"><strong>J</strong></td><td style="text-align:left;"><code>BANCO</code></td><td style="text-align:left;"><code>=IFERROR(INDEX(GERAL[BANCO],MATCH(PARCELAS[[#This Row],[NOME]],GERAL[NOME],0)),&quot;-&quot;)</code></td></tr><tr><td style="text-align:center;"><strong>K</strong></td><td style="text-align:left;"><code>SALDO DEVEDOR</code></td><td style="text-align:left;">Fórmula dinâmica de amortização progressiva</td></tr><tr><td style="text-align:center;"><strong>L</strong></td><td style="text-align:left;"><code>DIA</code></td><td style="text-align:left;"><code>=IF(OR(ISBLANK(...), DAY(...)=0), &quot;&quot;, TEXT(DAY(...), &quot;00&quot;))</code></td></tr><tr><td style="text-align:center;"><strong>M</strong></td><td style="text-align:left;"><code>MÊS</code></td><td style="text-align:left;"><code>=IF(ISBLANK(...), &quot;&quot;, INDEX(MESES[MÊS], MATCH(MONTH(...), MESES[N], 0)))</code></td></tr><tr><td style="text-align:center;"><strong>N</strong></td><td style="text-align:left;"><code>ANO</code></td><td style="text-align:left;"><code>=IF(OR(ISBLANK(...), YEAR(...)=1900), &quot;&quot;, YEAR(...))</code></td></tr><tr><td style="text-align:center;"><strong>O</strong></td><td style="text-align:left;"><code>CIDADE / UF</code></td><td style="text-align:left;"><code>Maceió - AL</code> ou <code>Barra de São Miguel - AL</code></td></tr></tbody></table><h2 id="tabela-auxiliar-meses-colunas-q-e-r" tabindex="-1">Tabela Auxiliar: <code>MESES</code> (Colunas Q e R) <a class="header-anchor" href="#tabela-auxiliar-meses-colunas-q-e-r" aria-label="Permalink to &quot;Tabela Auxiliar: `MESES` (Colunas Q e R)&quot;">​</a></h2><p>Para desobstruir a linha de visualização principal e garantir compatibilidade com versões antigas do Excel que não suportam a função <code>TEXT(data, &quot;mmmm&quot;)</code> em português, a tabela <code>MESES</code> foi alocada no intervalo <code>Q1:R13</code>:</p><ul><li>Coluna Q (<code>N</code>): 1 a 12</li><li>Coluna R (<code>MÊS</code>): janeiro, fevereiro, março, ..., dezembro</li></ul><h2 id="protecao-contra-corrupcao-de-grafico-chart1-xml" tabindex="-1">Proteção Contra Corrupção de Gráfico (<code>chart1.xml</code>) <a class="header-anchor" href="#protecao-contra-corrupcao-de-grafico-chart1-xml" aria-label="Permalink to &quot;Proteção Contra Corrupção de Gráfico (`chart1.xml`)&quot;">​</a></h2><p>Ao salvar a pasta de trabalho com o <strong>ClosedXML</strong>:</p><ul><li>O arquivo é copiado para um buffer em memória (<code>byte[]</code>).</li><li>As alterações de células afetam estritamente os nós XML necessários (<code>sheet2.xml</code>).</li><li>Todos os arquivos auxiliares do pacote OpenXML (<code>xl/drawings/drawing1.xml</code>, <code>xl/charts/chart1.xml</code>, <code>xl/calcChain.xml</code>) são preservados integralmente sem truncamento de stream.</li></ul>',15)])])}const A=e(l,[["render",r]]);export{u as __pageData,A as default};
